module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);


reg wen, ren;
reg [($clog2(DEPTH))-1:0] waddr, raddr;
reg [($clog2(DEPTH))-1:0] waddr_bin, raddr_bin;
reg [3:0] wptr, rptr;
reg [3:0] wptr_buff, rptr_buff;
reg [3:0] wptr_syn, rptr_syn;
reg wfull_reg, rempty_reg;
reg [WIDTH-1:0] rdata_reg;

assign wen = winc & !wfull;
assign ren = rinc & !rempty;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr <= 0;
    end else if (winc && !wfull) begin
        waddr <= waddr + 1;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr <= 0;
    end else if (rinc && !rempty) begin
        raddr <= raddr + 1;
    end
end

always @(*) begin
    wptr[3] = waddr_bin[3];
    wptr[2] = waddr_bin[3] ^ waddr_bin[2];
    wptr[1] = waddr_bin[2] ^ waddr_bin[1];
    wptr[0] = waddr_bin[1] ^ waddr_bin[0];
end

always @(*) begin
    rptr[3] = raddr_bin[3];
    rptr[2] = raddr_bin[3] ^ raddr_bin[2];
    rptr[1] = raddr_bin[2] ^ raddr_bin[1];
    rptr[0] = raddr_bin[1] ^ raddr_bin[0];
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_buff <= 0;
    end else begin
        wptr_buff <= wptr;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_buff <= 0;
    end else begin
        rptr_buff <= rptr;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_syn <= 0;
    end else begin
        wptr_syn <= wptr_buff;
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_syn <= 0;
    end else begin
        rptr_syn <= rptr_buff;
    end
end

always @(*) begin
    wfull_reg = (wptr == {~rptr_syn[3], rptr_syn[2:0]});
    rempty_reg = (rptr == wptr_syn);
end

assign wfull = wfull_reg;
assign rempty = rempty_reg;
assign rdata = rdata_reg;

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
